cross join (values
    ('Granite cornerstone with engraved date', 'Look for a large squared granite block at the building''s foundation corner with chiseled numbers showing the year carved into its surface.', 'Capture a gray granite stone block with clearly visible engraved numbers showing a date. The numerals must be legible and carved into the stone surface.', 'common'::public.item_rarity, 'Granite''s extreme hardness made hand-engraving dates so laborious that masons often worked 1-2 hours per digit.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/084b4ac9f6ec6ffe.jpg', 0),
    ('Bronze commemorative plaque', 'Find a shiny or patina-darkened bronze rectangle mounted on the building''s exterior wall with raised lettering about the building''s history.', 'Frame a bronze or copper-colored metal plaque mounted on a building or stone. The plaque must display commemorative text or inscriptions clearly visible.', 'common'::public.item_rarity, 'Bronze plaques develop a protective green patina (verdigris) within 3-5 years that actually prevents further corrosion.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/fa9b42dc8ea7c556.jpg', 1),
    ('Limestone building dedication marker', 'Search the building facade for a tan or cream-colored stone tablet with carved or relief text honoring the building''s opening or purpose.', 'Show a light-colored limestone stone with dedication text or inscription carved into its surface. Text must be readable and relate to building dedication.', 'common'::public.item_rarity, 'Limestone plaques deteriorate faster in polluted urban air due to acid rain converting calcium carbonate to soluble gypsum.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/25f9725ee64da23d.jpg', 2),
    ('Cast iron founding date plaque', 'Look for a dark, weathered metal plaque bolted to the building exterior with the founding year stamped or cast into its surface.', 'Photograph a dark cast iron plaque featuring engraved or embossed founding date numbers. The date must be clearly distinguishable on the iron surface.', 'common'::public.item_rarity, 'Cast iron plaques can last 200+ years if protected, but rust propagation from a single chip can destroy the entire plaque within 10 years if untreated.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/f5550f374cecbd3e.jpg', 3),
    ('Marble cornerstone inscription', 'Check the building''s corners for a white or light-colored marble block with engraved text marking the building''s establishment.', 'Capture a white or light-colored marble stone block with engraved text or inscription visible on its surface. The carved lettering must be legible.', 'common'::public.item_rarity, 'Marble inscriptions require re-chiseling every 80-100 years due to acid rain erosion, making truly ancient carved dates rare.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/aa479708571c21fa.jpg', 4),
    ('Sandstone architectural heritage plaque', 'Hunt for a reddish or tan-colored stone slab on the building''s wall with carved symbols or text identifying it as architecturally significant.', 'Frame a tan or reddish-brown sandstone plaque with carved architectural heritage text or symbols. Inscription must be clearly visible on the stone.', 'uncommon'::public.item_rarity, 'Sandstone''s porosity makes it absorb urban pollution; plaques exposed to car exhaust degrade 3-4 times faster than rural examples.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/1caca10c8408e53b.jpg', 5),
    ('Brass historic landmark plaque', 'Spot a golden-toned brass plate affixed to the building with embossed or engraved writing explaining why it''s historically important.', 'Show a golden or brassy-colored metal plaque with engraved historic landmark information. The text and decorative elements must be clearly readable.', 'common'::public.item_rarity, 'Brass plaques develop a distinctive blackish patina (cuprous oxide) that actually stabilizes the surface and slows further tarnishing.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/fa9b42dc8ea7c556.jpg', 6),
    ('Engraved foundation stone', 'Look down at the building''s base for a stone block with deeply cut letters or dates carved directly into its surface.', 'Capture a stone block with engraved text or numbers indicating foundation information. Engravings must be deeply carved and legible in the image.', 'uncommon'::public.item_rarity, 'Foundation stone engraving depths varied wildly (0.5-3mm) based on mason skill, making shallow inscriptions nearly invisible after 150+ years.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/66c5f4744a5d48c3.jpg', 7),
    ('Carved stone building name plaque', 'Look for the building''s name chiseled directly into a stone section of the facade or entrance area in readable, relief lettering.', 'Photograph a stone plaque with building name carved or embossed into its surface. The name lettering must be clearly visible and readable.', 'common'::public.item_rarity, 'Stone carvers used multiple chisels per letter; the angle and tool marks left distinctive signatures that conservators use to identify individual craftsmen.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/627a3c1cd1c8885d.jpg', 8),
    ('Metal heritage society plaque', 'Find a metal nameplate mounted on the building that credits a heritage society or preservation organization as a marker of historical recognition.', 'Frame a metal plaque (any color) displaying heritage society name, seal, or certification text. Text and emblems must be clearly engraved or embossed.', 'uncommon'::public.item_rarity, 'Early heritage society plaques (pre-1950) often used alloys that corrode in specific patterns, creating dated fingerprints for when plaques were cast.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/15d052ab0f5bb00f.jpg', 9),
    ('Granite memorial cornerstone', 'Locate a large gray granite block at a building corner with inscribed text memorializing an important person or event.', 'Capture a gray granite corner stone with memorial inscriptions or text engraved on its surface. Lettering must be clearly legible in the frame.', 'uncommon'::public.item_rarity, 'Granite cornerstones were typically 18-24 inches cubed and weighed 600+ pounds; placing them required specialized rigging no longer documented.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/65c086ce7bcdd7db.jpg', 10),
    ('Embossed masonry date marker', 'Search the building walls for a raised date pushed outward from the brick or stone surface, often marking construction or renovation years.', 'Show a masonry stone with embossed or raised date numerals. The date numbers must stand out visibly from the stone surface.', 'uncommon'::public.item_rarity, 'Embossed (raised) markers weather unevenly—tops erode 40-60% faster than recessed areas due to concentrated rain and wind exposure.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/dd718dad34004485.jpg', 11),
    ('Historic society certification plaque', 'Look for an official-looking plaque from a historical society or heritage board, usually small and mounted prominently on the building.', 'Photograph a plaque bearing historic society certification marks, name, or logos. Official certification language or emblems must be clearly visible.', 'rare'::public.item_rarity, 'Certification plaques installed post-1960 were often bronze-colored aluminum, not actual bronze, making them vulnerable to oxidation that bronze resists.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/d2036bd9061a036a.jpg', 12),
    ('Architect''s signature stone plaque', 'Hunt for a stone tablet near the entrance with the architect or builder''s name carved into it, sometimes with their dates or initials.', 'Capture a stone plaque displaying an architect''s name or signature carved or engraved into the surface. The signature must be clearly readable.', 'rare'::public.item_rarity, 'Few architects signed building stones directly; when found, signatures help resolve disputed building attribution that paper records sometimes contradict.', 'https://cejsntpvctcgezrluvql.supabase.co/storage/v1/object/public/collection-item-images/00000000-0000-0000-0000-000000000001/wiki-cache/bf9ba54c90d8778e.jpg', 13),
    ('Original street address stone carving', 'Check near the building''s entrance or street-facing wall for numbers carved or embossed directly into stone showing the old address.', 'Frame a stone with street address numbers or text carved into its surface. Address numerals or text must be legible and historically original-appearing.', 'rare'::public.item_rarity, 'Street number stones absorbed street-level pollutants intensely; many pre-1900 numbers are illegible despite surviving physically.', null, 14)
